/*
 * A319151  Heinz numbers of superperiodic integer partitions.
 * https://oeis.org/A319151
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the nth number n>1 such that either n=2 or - all prime
 *            indices of the prime factors of n have a common divisor >1, and
 *            - the Heinz number of the multiset of exponents of n is already
 *            in the sequence. The sequence is generated by scanning integers
 *            in order, storing each accepted number in...
 * Range:     u8 n <= 63, u16 n <= 2326, u32 n <= 2326, u64 n <= 2326,
 *            u128 n <= 2326, big any n
 * Validated: standard, pass, 75 terms through n = 2262 (2026-11-03)
 * Helpers:   build_primes_upto, factor_u64, gcd, isqrt, mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stddef.h>

#include <stdbool.h>
#include "../utils/build_primes_upto.h"
#include "../utils/factor_u64.h"
#include "../utils/gcd.h"
#include "../utils/isqrt.h"
#include "../utils/mem.h"

/* Return the k‑th prime (k ≥ 1).  On first call the prime list
   is built incrementally using trial division.  The list is
   stored in a static array which is expanded as necessary.   */
static uint32_t get_prime(idx_t k)
{
    static uint32_t *pr = NULL;     /* array of primes */
    static size_t sz   = 0;         /* number of primes stored */
    static size_t cap  = 0;         /* allocated capacity */
    static uint32_t cand = 3;       /* candidate after 2 */

    /* initialise the prime table on first use */
    if (sz == 0) {
        cap = 8;
        pr = (uint32_t *)realloc(pr, cap * sizeof(uint32_t));
        if (!pr) abort();
        sz = 0;
    }

    /* grow the array until we have at least k primes */
    while (sz < (size_t)k) {
        if (sz == 0) {                /* add the first prime */
            pr[sz++] = 2;
            continue;
        }

        /* find the next prime candidate */
        uint32_t p = cand;
        bool ok = true;
        for (size_t i = 0; i < sz; ++i) {
            uint32_t prime = pr[i];
            if ((uint64_t)prime * prime > (uint64_t)p) break;
            if (p % prime == 0) { ok = false; break; }
        }

        if (!ok) {                    /* not prime – keep searching */
            cand += 2;                /* only odd numbers remain */
            continue;
        }

        /* prime found – store it, grow table if needed */
        if (sz == cap) {
            cap <<= 1;
            pr = (uint32_t *)realloc(pr, cap * sizeof(uint32_t));
            if (!pr) abort();
        }
        pr[sz++] = p;
        cand = p + 2;
    }

    return pr[(size_t)k - 1];
}

static seq_t *seq           = NULL;  /* sequence values */
static size_t  seq_len      = 0;      /* number of stored terms   */
static size_t  seq_cap      = 0;      /* current capacity        */

static uint64_t *prime_cache = NULL; /* list of primes for index lookup */
static size_t   prime_cnt    = 0;

static uint64_t checked_upto = 1;     /* last integer examined */

/* --------------------------------------------------------------------- */
/* Utility: binary search for uint64_t in sorted array                  */
static size_t binary_search_uint64(const uint64_t *arr, size_t n, uint64_t key)
{
    size_t lo = 0, hi = n;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (arr[mid] < key)
            lo = mid + 1;
        else
            hi = mid;
    }
    /* element must exist in prime_cache by construction */
    return lo;   /* index where arr[idx] == key */
}

/* --------------------------------------------------------------------- */
/* Utility: binary search for seq_t in sorted array (sequence)          */
static int binary_search_seq(seq_t *arr, size_t n, seq_t key)
{
    size_t lo = 0, hi = n;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (arr[mid] < key)
            lo = mid + 1;
        else
            hi = mid;
    }
    return (lo < n && arr[lo] == key) ? 1 : 0;
}

/* --------------------------------------------------------------------- */
/* Initialise prime cache up to a modest limit (200 000)                 */
/* This suffices for n up to about 10 000 in the sequence.               */
static void init_prime_cache(void)
{
    static int done = 0;
    if (done) return;
    size_t cnt;
    uint64_t *primes;
    build_primes_upto(200000, &primes, &cnt);   /* primes <= 200 000 */
    prime_cache = primes;
    prime_cnt   = cnt;
    done = 1;
}

/* --------------------------------------------------------------------- */
/* Ensure the sequence has at least n terms (n≥1).  Generate if necessary*/
/* --------------------------------------------------------------------- */
static void ensure_sequence_upto(idx_t n)
{
    if (seq_len >= (size_t)n) return;
    init_prime_cache();

    /* temporary arrays for factorisation */
    uint64_t primes_tmp[64];
    uint64_t exps_tmp[64];
    size_t   num_factors;

    while (seq_len < (size_t)n) {
        ++checked_upto;                /* next candidate integer    */
        uint64_t cand = checked_upto;

        /* trivial acceptance of 2 */
        if (cand == 2) {
            if (seq_cap == seq_len) {
                seq_cap = seq_cap ? seq_cap * 2 : 4;
                seq = mem_resize(seq_t, seq, seq_cap);
            }
            seq[seq_len++] = (seq_t)2;
            continue;
        }

        /* factorise cand */
        factor_u64(cand, primes_tmp, exps_tmp, &num_factors);
        if (num_factors == 0) continue;   /* should not happen */

        /* compute gcd of prime indices */
        seq_t idx_gcd = 0;
        for (size_t i = 0; i < num_factors; ++i) {
            uint64_t p   = primes_tmp[i];
            size_t   pos = binary_search_uint64(prime_cache, prime_cnt, p);
            seq_t    idx = (seq_t)(pos + 1);   /* indices start at 1 */
            if (i == 0) idx_gcd = idx;
            else        idx_gcd = gcd(idx_gcd, idx);
            if (idx_gcd <= 1) break;           /* early exit */
        }
        if (idx_gcd <= 1) continue;             /* fails first test */

        /* compute Heinz number of exponents */
        seq_t heinz = 1;
        for (size_t i = 0; i < num_factors; ++i) {
            uint64_t e = exps_tmp[i];
            seq_t    prime_of_e = (seq_t)get_prime(e);
            heinz *= prime_of_e;
        }

        /* check if Heinz number already in sequence */
        if (!binary_search_seq(seq, seq_len, heinz))
            continue;                        /* fails second test */

        /* accept candidate */
        if (seq_cap == seq_len) {
            seq_cap = seq_cap ? seq_cap * 2 : 4;
            seq = mem_resize(seq_t, seq, seq_cap);
        }
        seq[seq_len++] = (seq_t)cand;
    }
}

/* --------------------------------------------------------------------- */
/* Public function required by the harness                              */
/* --------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    /* the sequence is 1‑based; seq[0] holds a(1) */
    ensure_sequence_upto(n);
    return seq[n - 1];
}
